-- =============================================================================
-- School Store — inventory numbers and shopping trips (phase 4)
-- =============================================================================
--   inventory_snapshot()   everything the Inventory page needs, in one call
--   save_expense(json)     records a shopping trip and adds the stock
--   delete_expense(id)     removes a trip that was entered by mistake
-- =============================================================================


-- -----------------------------------------------------------------------------
-- inventory_snapshot
-- -----------------------------------------------------------------------------
-- "Units sold" counts every unit that was PAID FOR (online pickups and
-- imported in-person sales), read from the stock history. The averaging
-- window is the sales_average_days setting, shortened if the store doesn't
-- have that much history yet (so a new store isn't under-counted).
create or replace function public.inventory_snapshot()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  s            public.settings;
  v_today      date := public.store_today();
  v_first_sale date;
  v_days       int;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select * into s from public.settings where id = 1;

  select min(effective_date) into v_first_sale
  from public.stock_movements
  where reason in ('sale_import', 'online_pickup');

  v_days := greatest(1, least(s.sales_average_days, v_today - coalesce(v_first_sale, v_today) + 1));

  return jsonb_build_object(
    'today', v_today,
    'window_days', v_days,
    'reorder_buffer_days', s.reorder_buffer_days,
    'shopping_interval_days', s.shopping_interval_days,
    'next_shopping_date', s.next_shopping_date,
    'products', coalesce((
      select jsonb_agg(row_to_json(t) order by t.name)
      from (
        select
          p.id, p.name, p.category, p.emoji, p.photo_path,
          p.stock, coalesce(r.reserved, 0) as reserved,
          p.price_cents, p.unit_cost_cents, p.reorder_point, p.lead_days,
          p.is_perishable, p.available_online,
          sup.name as supplier,
          -- units paid for in the window
          coalesce((
            select -sum(m.change)
            from public.stock_movements m
            where m.product_id = p.id
              and m.reason in ('sale_import', 'online_pickup', 'online_pickup_undo')
              and m.effective_date > v_today - v_days
          ), 0)::int as units_sold,
          -- perishable batches, newest first (for expiration dates)
          case when p.is_perishable then coalesce((
            select jsonb_agg(jsonb_build_object(
                     'quantity', b.quantity, 'received_on', b.received_on, 'expires_on', b.expires_on)
                   order by b.received_on desc, b.created_at desc)
            from public.product_batches b where b.product_id = p.id
          ), '[]'::jsonb) end as batches
        from public.products p
        left join public.product_reserved r on r.product_id = p.id
        left join public.suppliers sup on sup.id = p.supplier_id
        where not p.archived
      ) t), '[]'::jsonb)
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- save_expense
-- -----------------------------------------------------------------------------
-- p is a JSON object:
-- {
--   "purchased_on": "2026-10-26", "supplier_id": "...", "buyer_name": "Ms. A",
--   "receipt_path": "2026/10/abc.jpg", "notes": "...",
--   "items": [
--     { "product_id": "...", "description": "Hot Cheetos", "quantity": 24,
--       "unit_cost_cents": 55, "update_cost": true, "expires_on": null },
--     { "product_id": null, "description": "Napkins", "quantity": 1, "unit_cost_cents": 649 }
--   ]
-- }
-- Everything happens together: if any line is bad, nothing is saved.
create or replace function public.save_expense(p jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_id      uuid;
  v_item    jsonb;
  v_product public.products;
  v_qty     int;
  v_cost    int;
  v_date    date := (p->>'purchased_on')::date;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if v_date is null or v_date > public.store_today() then
    raise exception 'BAD_DATE' using hint = 'Choose the day of the trip (it can''t be in the future).';
  end if;
  if coalesce(btrim(p->>'buyer_name'), '') = '' then
    raise exception 'NO_BUYER' using hint = 'Enter who did the shopping.';
  end if;
  if jsonb_typeof(p->'items') <> 'array' or jsonb_array_length(p->'items') = 0 then
    raise exception 'NO_ITEMS' using hint = 'Add at least one item.';
  end if;

  insert into public.expenses (purchased_on, supplier_id, buyer_name, receipt_path, notes, created_by)
  values (v_date, nullif(p->>'supplier_id', '')::uuid, btrim(p->>'buyer_name'),
          nullif(p->>'receipt_path', ''), nullif(btrim(p->>'notes'), ''), auth.uid())
  returning id into v_id;

  for v_item in select * from jsonb_array_elements(p->'items') loop
    v_qty  := (v_item->>'quantity')::int;
    v_cost := (v_item->>'unit_cost_cents')::int;
    if v_qty is null or v_qty < 1 or v_cost is null or v_cost < 0 then
      raise exception 'BAD_LINE' using hint = 'Every line needs a quantity of 1 or more and a cost.';
    end if;

    v_product := null;
    if nullif(v_item->>'product_id', '') is not null then
      select * into v_product from public.products where id = (v_item->>'product_id')::uuid;
      if not found then
        raise exception 'BAD_PRODUCT' using hint = 'One of the products no longer exists.';
      end if;
    end if;

    insert into public.expense_items (expense_id, product_id, description, quantity, unit_cost_cents)
    values (v_id, v_product.id,
            coalesce(nullif(btrim(v_item->>'description'), ''), v_product.name, 'Supplies'),
            v_qty, v_cost);

    if v_product.id is not null then
      -- Add to stock.
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_product.id, v_qty, 'restock', v_date, 'Shopping trip', v_id, auth.uid());

      -- Remember the expiration date for perishables.
      if v_product.is_perishable and nullif(v_item->>'expires_on', '') is not null then
        insert into public.product_batches (product_id, quantity, received_on, expires_on, expense_id)
        values (v_product.id, v_qty, v_date, (v_item->>'expires_on')::date, v_id);
      end if;

      -- Optionally update the product's cost to this trip's price.
      if coalesce((v_item->>'update_cost')::boolean, false) then
        update public.products set unit_cost_cents = v_cost where id = v_product.id;
      end if;
    end if;
  end loop;

  update public.expenses e
     set total_cents = (select coalesce(sum(line_total_cents), 0) from public.expense_items where expense_id = e.id)
   where e.id = v_id;

  return v_id;
end;
$$;


-- -----------------------------------------------------------------------------
-- delete_expense
-- -----------------------------------------------------------------------------
-- For trips entered by mistake. Takes back the stock it added (as a new
-- history line, so the history stays honest), then deletes the trip.
-- Product costs that were updated are NOT changed back.
create or replace function public.delete_expense(p_expense_id uuid)
returns text
language plpgsql security definer
set search_path = public
as $$
declare
  v_receipt text;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select receipt_path into v_receipt from public.expenses where id = p_expense_id;
  if not found then
    raise exception 'NOT_FOUND' using hint = 'That shopping trip no longer exists.';
  end if;

  insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
  select m.product_id, -sum(m.change)::int, 'manual_adjustment', public.store_today(),
         'Shopping trip deleted (entered by mistake)', p_expense_id, auth.uid()
  from public.stock_movements m
  where m.source_id = p_expense_id and m.reason = 'restock'
  group by m.product_id
  having sum(m.change) <> 0;

  delete from public.expenses where id = p_expense_id;  -- items and batches go with it

  return v_receipt;  -- so the website can delete the receipt file too
end;
$$;


revoke execute on function public.inventory_snapshot()   from public, anon;
revoke execute on function public.save_expense(jsonb)    from public, anon;
revoke execute on function public.delete_expense(uuid)   from public, anon;
grant  execute on function public.inventory_snapshot()   to authenticated;
grant  execute on function public.save_expense(jsonb)    to authenticated;
grant  execute on function public.delete_expense(uuid)   to authenticated;

